<?php
namespace App\Http\Controllers\CRM; use App\Http\Controllers\Controller; use App\Models\{Guest,GuestFeedback}; use Illuminate\Http\Request;
class FeedbackController extends Controller {public function index(){ $p=auth()->user()->property_id; return view('crm.feedback',['feedback'=>GuestFeedback::where('property_id',$p)->with('guest')->latest()->paginate(30),'guests'=>Guest::where('property_id',$p)->orderBy('first_name')->limit(250)->get()]);} public function store(Request $r){$d=$r->validate(['guest_id'=>'nullable|exists:guests,id','rating'=>'required|integer|min:1|max:5','room_rating'=>'nullable|integer|min:1|max:5','service_rating'=>'nullable|integer|min:1|max:5','food_rating'=>'nullable|integer|min:1|max:5','comments'=>'nullable|string','permission_to_publish'=>'nullable|boolean']);$d+=['property_id'=>auth()->user()->property_id,'channel'=>'internal','submitted_at'=>now()];GuestFeedback::create($d);return back()->with('success','Feedback recorded.');}}
